import React, { useEffect, useMemo, useRef, useState } from "react";
import { Album, ChevronLeft, ChevronRight, Clock3, Compass, ExternalLink, Heart, Home as HomeIcon, Library, ListMusic, Loader2, Pause, Play, Search, SkipBack, SkipForward, Sparkles, Volume2, VolumeX } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { trpc } from "@/lib/trpc";
import { catalogRepository, libraryRepository, type LocalLibraryState, type LocalStationCatalog } from "@/lib/localPersistence";
import { getLiveSearchQuery } from "@/lib/liveSearch";
import { getPlaybackAvailability, getPlaybackErrorMessage } from "@/lib/playbackState";
import { ButterchurnVisualizer } from "@/components/ButterchurnVisualizer";
import { FullSignal } from "@/components/FullSignal";
import { getOrCreateVisualAudioGraph } from "@/lib/audioGraph";

export type Track = { id: string; source: "spotify" | "musicbrainz" | "audius" | "jamendo"; kind: "track" | "album"; name: string; artist: string; album: string; releaseYear: string; durationMs: number; durationLabel: string; popularity: number; imageUrl: string | null; spotifyUrl: string; previewUrl: string | null; availableMarkets: string[]; licenseLabel: string; attribution: string; licenseUrl: string | null; matchMode?: "strict" | "discovery" };
type View = "home" | "search" | "library";
function isPlayableTrack(track: Track) { return Boolean(track.previewUrl?.trim()); }
function dedupePlayableTracks(tracks: Track[]) { const seen = new Set<string>(); return tracks.filter(track => { if (!isPlayableTrack(track) || seen.has(`${track.source}:${track.id}`)) return false; seen.add(`${track.source}:${track.id}`); return true; }); }
function normalizedTrackValue(value: string) { return value.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase(); }
export function prepareAutoplayQueue(current: Track, queue: Track[], catalogue: Track[], limit = 3) { const candidates: Track[] = []; const seen = new Set<string>([current.id]); const add = (track: Track) => { if (isPlayableTrack(track) && !seen.has(track.id)) { seen.add(track.id); candidates.push(track); } }; const playableQueue = queue.filter(isPlayableTrack); const currentIndex = playableQueue.findIndex(track => track.id === current.id); if (currentIndex >= 0) playableQueue.slice(currentIndex + 1).forEach(add); const currentArtist = normalizedTrackValue(current.artist); const currentAlbum = normalizedTrackValue(current.album); const currentWords = normalizedTrackValue(`${current.name} ${current.artist}`).split(/\s+/).filter(word => word.length > 2); catalogue.filter(track => isPlayableTrack(track) && !seen.has(track.id)).map(track => { const haystack = normalizedTrackValue(`${track.name} ${track.artist} ${track.album}`); const sharedWords = currentWords.filter(word => haystack.includes(word)).length; const sameArtist = normalizedTrackValue(track.artist) === currentArtist; const sameAlbum = normalizedTrackValue(track.album) === currentAlbum; return { track, score: (sameArtist ? 100 : 0) + (sameAlbum ? 35 : 0) + (track.source === current.source ? 8 : 0) + sharedWords * 4 + track.popularity / 1000 }; }).sort((a, b) => b.score - a.score).forEach(({ track }) => add(track)); return candidates.slice(0, Math.max(1, limit)); }
export function pickAutoplayTrack(current: Track, queue: Track[], catalogue: Track[]) { return prepareAutoplayQueue(current, queue, catalogue, 1)[0]; }
const IDLE_TRACK: Track = { id: "idle", source: "musicbrainz", kind: "track", name: "Sonic//Void listo", artist: "Elegí una señal para comenzar", album: "Local mode", releaseYear: "—", durationMs: 0, durationLabel: "0:00", popularity: 0, imageUrl: null, spotifyUrl: "#", previewUrl: null, availableMarkets: [], licenseLabel: "—", attribution: "—", licenseUrl: null };

function Cover({ track, large = false }: { track: Track; large?: boolean }) {
  return track.imageUrl ? <img src={track.imageUrl} alt={`Carátula de ${track.album}`} className={`h-full w-full object-cover ${large ? "" : "transition duration-500 group-hover:scale-105"}`} /> : <div className="grid h-full w-full place-items-center bg-[#151722] text-[#ff2db2]"><Album size={large ? 42 : 24} /></div>;
}

export default function Home() {
  const initialQuery = typeof window !== "undefined" ? new URLSearchParams(window.location.search).get("q")?.trim() ?? "" : "";
  const [view, setView] = useState<View>(initialQuery ? "search" : "home");
  const [term, setTerm] = useState(initialQuery);
  const [submitted, setSubmitted] = useState(initialQuery);
  const [offset, setOffset] = useState(0);
  const [tracks, setTracks] = useState<Track[]>([]);
  const [selected, setSelected] = useState<Track | null>(null);
  const [playing, setPlaying] = useState<Track | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [playbackNotice, setPlaybackNotice] = useState<string | null>(null);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [volume, setVolume] = useState(() => libraryRepository.load().preferences.volume);
  const [muted, setMuted] = useState(() => libraryRepository.load().preferences.muted);
  const [library, setLibrary] = useState<LocalLibraryState>(() => libraryRepository.load());
  const [autoplaySeed, setAutoplaySeed] = useState<Track | null>(null);
  const [autoplayQueue, setAutoplayQueue] = useState<Track[]>([]);
  const [activeStation, setActiveStation] = useState<string | null>(null);
  const [pendingStationQuery, setPendingStationQuery] = useState<string | null>(null);
  const [stationCatalog, setStationCatalog] = useState<LocalStationCatalog>(() => catalogRepository.load());
  const status = trpc.music.status.useQuery(undefined, { refetchInterval: 30_000 });
  const searchInput = useMemo(() => ({ query: submitted, offset }), [submitted, offset]);
  const autoplayInput = useMemo(() => ({ query: autoplaySeed ? autoplaySeed.artist : "", offset: 0 }), [autoplaySeed]);
  const afterglowInput = useMemo(() => ({ query: "underground lo-fi", offset: 0 }), []);
  const neonFocusInput = useMemo(() => ({ query: "experimental electronic", offset: 0 }), []);
  const openFrequencyInput = useMemo(() => ({ query: "underground punk", offset: 0 }), []);
  const freeJazzInput = useMemo(() => ({ query: "free jazz improvisation", offset: 0 }), []);
  const riotFolkInput = useMemo(() => ({ query: "riot folk protest", offset: 0 }), []);
  const lyricsInput = useMemo(() => selected ? { name: selected.name, artist: selected.artist, album: selected.album, duration: selected.durationMs } : { name: "", artist: "", album: "", duration: 0 }, [selected]);
  const search = trpc.music.search.useQuery(searchInput, { enabled: submitted.length > 0 });
  const autoplaySearch = trpc.music.search.useQuery(autoplayInput, { enabled: Boolean(autoplaySeed) });
  const afterglowSearch = trpc.music.search.useQuery(afterglowInput, { enabled: view === "home", staleTime: 300_000 });
  const neonFocusSearch = trpc.music.search.useQuery(neonFocusInput, { enabled: view === "home", staleTime: 300_000 });
  const openFrequencySearch = trpc.music.search.useQuery(openFrequencyInput, { enabled: view === "home", staleTime: 300_000 });
  const freeJazzSearch = trpc.music.search.useQuery(freeJazzInput, { enabled: view === "home", staleTime: 300_000 });
  const riotFolkSearch = trpc.music.search.useQuery(riotFolkInput, { enabled: view === "home", staleTime: 300_000 });
  const lyrics = trpc.music.lyrics.useQuery(lyricsInput, { enabled: Boolean(selected) });
  const stationSources = useMemo(() => [{ key: "afterglow", data: afterglowSearch.data?.items as Track[] | undefined }, { key: "neon-focus", data: neonFocusSearch.data?.items as Track[] | undefined }, { key: "riot-frequency", data: openFrequencySearch.data?.items as Track[] | undefined }, { key: "free-jazz", data: freeJazzSearch.data?.items as Track[] | undefined }, { key: "riot-folk", data: riotFolkSearch.data?.items as Track[] | undefined }], [afterglowSearch.data, neonFocusSearch.data, openFrequencySearch.data, freeJazzSearch.data, riotFolkSearch.data]);
  const stationTracks = (key: string, fresh: Track[] | undefined) => { const cached = (stationCatalog[key]?.tracks as Track[] | undefined) ?? []; return dedupePlayableTracks([...(fresh ?? []), ...cached]); };
  const starterStations = useMemo(() => [{ name: "Relax", query: "ambient downtempo", detail: "Ambient · downtempo · respiración", artUrl: "/manus-storage/nowarfy-relax_918567ef.jpg", tracks: stationTracks("afterglow", afterglowSearch.data?.items as Track[] | undefined) }, { name: "Focus", query: "instrumental electronic", detail: "Instrumental · electrónica · concentración", artUrl: "/manus-storage/nowarfy-focus_15f606bc.jpg", tracks: stationTracks("neon-focus", neonFocusSearch.data?.items as Track[] | undefined) }, { name: "Workout", query: "high energy rock", detail: "Rock · energía · movimiento", artUrl: "/manus-storage/nowarfy-workout_e77833d0.jpg", tracks: stationTracks("riot-frequency", openFrequencySearch.data?.items as Track[] | undefined) }, { name: "Energize", query: "upbeat funk", detail: "Funk · groove · impulso", artUrl: "/manus-storage/nowarfy-energize_d0b96f48.jpg", tracks: stationTracks("free-jazz", freeJazzSearch.data?.items as Track[] | undefined) }, { name: "Sleep", query: "sleep ambient", detail: "Ambient · nocturna · descanso", artUrl: "/manus-storage/nowarfy-sleep_c3d6e86d.jpg", tracks: stationTracks("riot-folk", riotFolkSearch.data?.items as Track[] | undefined) }], [stationCatalog, afterglowSearch.data, neonFocusSearch.data, openFrequencySearch.data, freeJazzSearch.data, riotFolkSearch.data]);

  useEffect(() => { const data = search.data; if (!data || data.query !== submitted) return; const playable = (data.items as Track[]).filter(isPlayableTrack); setTracks(prev => offset === 0 ? playable : [...prev, ...playable]); }, [search.data, offset, submitted]);
  useEffect(() => { const clean = getLiveSearchQuery(term, submitted); if (!clean) return; const timer = window.setTimeout(() => { setView("search"); setOffset(0); setTracks([]); setSubmitted(clean); setSelected(null); }, 360); return () => window.clearTimeout(timer); }, [submitted, term]);
  useEffect(() => { libraryRepository.save(library); }, [library]);
  useEffect(() => { catalogRepository.save(stationCatalog); }, [stationCatalog]);
  useEffect(() => { const fresh = stationSources.filter(source => source.data?.some(isPlayableTrack)); if (!fresh.length) return; setStationCatalog(previous => { const next = { ...previous }; fresh.forEach(source => { const merged = dedupePlayableTracks([...(source.data ?? []), ...((previous[source.key]?.tracks as Track[] | undefined) ?? [])]); next[source.key] = { updatedAt: Date.now(), tracks: merged.slice(0, 40) }; }); return next; }); }, [stationSources]);

  const visibleTracks = useMemo(() => { const playable = tracks.filter(isPlayableTrack); return view === "library" ? playable.filter(track => library.favorites.includes(track.id)) : playable; }, [library.favorites, tracks, view]);
  const playableTracks = useMemo(() => tracks.filter(track => Boolean(track.previewUrl)), [tracks]);
  const queueTracks = useMemo(() => library.queue.filter(item => Boolean(item.previewUrl)), [library.queue]);
  const activeLyric = useMemo(() => { const lines = lyrics.data?.syncedLyrics ?? []; return lines.reduce<string | null>((current, line) => line.timeMs <= currentTime * 1000 ? line.text : current, null); }, [currentTime, lyrics.data?.syncedLyrics]);
  const submit = (event: React.FormEvent) => { event.preventDefault(); const clean = term.trim(); if (!clean) return; setActiveStation(null); setPendingStationQuery(null); setView("search"); setOffset(0); setTracks([]); setSubmitted(clean); setSelected(null); };
  const startStationSession = (station: RadioStation) => { setActiveStation(station.name); const first = station.tracks.find(isPlayableTrack); if (first) { setView("home"); setPendingStationQuery(null); playTrack(first); return; } setView("search"); setOffset(0); setTracks([]); setSubmitted(station.query); setSelected(null); setPendingStationQuery(station.query); setPlaybackNotice(`Buscando la primera pista reproducible de ${station.name}…`); };
  const toggleFavorite = (track: Track) => setLibrary(prev => ({ ...prev, favorites: prev.favorites.includes(track.id) ? prev.favorites.filter(id => id !== track.id) : [...prev.favorites, track.id] }));
  const addToQueue = (track: Track) => { if (!track.previewUrl) { setPlaybackNotice(`«${track.name}» no se agregó: no tiene audio reproducible.`); window.setTimeout(() => setPlaybackNotice(null), 4200); return; } setLibrary(prev => prev.queue.some(item => item.id === track.id) ? prev : { ...prev, queue: [...prev.queue, track] }); };
  const removeFromQueue = (trackId: string) => setLibrary(prev => ({ ...prev, queue: prev.queue.filter(item => item.id !== trackId) }));
  const clearQueue = () => setLibrary(prev => ({ ...prev, queue: [] }));
  const addToPlaylist = (track: Track) => { const name = window.prompt("Nombre de la playlist local"); const clean = name?.trim(); if (!clean) return; setLibrary(prev => { const existing = prev.playlists.find(item => item.name.toLowerCase() === clean.toLowerCase()); if (existing) return { ...prev, playlists: prev.playlists.map(item => item.id === existing.id ? { ...item, trackIds: item.trackIds.includes(track.id) ? item.trackIds : [...item.trackIds, track.id] } : item) }; return { ...prev, playlists: [...prev.playlists, { id: `playlist-${Date.now()}`, name: clean, trackIds: [track.id], createdAt: Date.now() }] }; }); }; 
  const createPlaylist = () => { const name = window.prompt("Nombre de la playlist local"); const clean = name?.trim(); if (!clean) return; setLibrary(prev => prev.playlists.some(item => item.name.toLowerCase() === clean.toLowerCase()) ? prev : { ...prev, playlists: [...prev.playlists, { id: `playlist-${Date.now()}`, name: clean, trackIds: [], createdAt: Date.now() }] }); };
  const playTrack = (track: Track) => { setSelected(track); if (!track.previewUrl) { setPlaybackNotice(`«${track.name}» no tiene un audio reproducible en la fuente disponible.`); window.setTimeout(() => setPlaybackNotice(null), 4200); return; } setPlaybackNotice(null); setPlaying(track); setLibrary(prev => prev.queue.some(item => item.id === track.id) ? prev : { ...prev, queue: [track, ...prev.queue] }); setAutoplayQueue(prepareAutoplayQueue(track, [...queueTracks, track], playableTracks, 3)); setAutoplaySeed(track); setCurrentTime(0); setIsPlaying(true); };
  useEffect(() => { if (!pendingStationQuery || search.isFetching || search.data?.query !== pendingStationQuery) return; const first = (search.data.items as Track[]).find(isPlayableTrack); if (!first) return; setPendingStationQuery(null); setPlaybackNotice(null); setView("home"); playTrack(first); }, [pendingStationQuery, search.data, search.isFetching]);
  useEffect(() => { if (!autoplaySeed || !autoplaySearch.data) return; const prepared = prepareAutoplayQueue(autoplaySeed, queueTracks, (autoplaySearch.data.items as Track[]).filter(isPlayableTrack), 3); setAutoplayQueue(previous => { const seen = new Set(previous.map(track => track.id)); return [...previous, ...prepared.filter(track => !seen.has(track.id))].slice(0, 3); }); setAutoplaySeed(null); }, [autoplaySearch.data, autoplaySeed, queueTracks]);
  const moveTrack = (direction: 1 | -1) => { if (!playing || !queueTracks.length) return; const index = queueTracks.findIndex(item => item.id === playing.id); const next = queueTracks.length > 1 ? queueTracks[(index + direction + queueTracks.length) % queueTracks.length] : undefined; if (next) playTrack(next); };
  const advanceTrack = () => { if (!playing) return; const next = autoplayQueue[0] ?? pickAutoplayTrack(playing, queueTracks, playableTracks); if (next) { setAutoplayQueue(previous => previous.filter(track => track.id !== next.id)); playTrack(next); return; } setIsPlaying(false); setPlaybackNotice("La cola anticipada quedó vacía; buscando una señal similar…"); setAutoplaySeed(playing); };
  const changeVolume = (nextVolume: number) => { const safe = Math.max(0, Math.min(1, nextVolume)); setVolume(safe); setMuted(safe === 0 ? true : muted); setLibrary(prev => ({ ...prev, preferences: { ...prev.preferences, volume: safe, muted: safe === 0 ? true : muted } })); };
  const toggleMute = () => { const nextMuted = !muted; setMuted(nextMuted); setLibrary(prev => ({ ...prev, preferences: { ...prev.preferences, muted: nextMuted } })); };
  const nav = (next: View) => { setView(next); if (next !== "search") setSubmitted(""); };

  return <main className="min-h-screen bg-[#07080c] pb-24 text-white">
    <div className="app-shell mx-auto flex min-h-screen max-w-[1600px]">
      <aside className="hidden w-64 shrink-0 border-r border-white/[.07] bg-[#0a0b10] p-6 lg:flex lg:flex-col">
        <div className="mb-12 flex items-center gap-3"><div className="grid h-10 w-10 place-items-center border border-[#ff2db2] text-[#ff2db2] shadow-[0_0_22px_rgba(255,45,178,.4)]"><Sparkles size={18} /></div><div><p className="font-mono text-[9px] uppercase tracking-[.3em] text-[#00e7ff]">Signal archive</p><h1 className="font-display text-lg font-black">SONIC<span className="text-[#ff2db2]">//</span>VOID</h1></div></div>
        <nav className="space-y-2"><NavItem active={view === "home"} icon={<HomeIcon size={18} />} label="Inicio" onClick={() => nav("home")} /><NavItem active={view === "search"} icon={<Search size={18} />} label="Buscar" onClick={() => nav("search")} /><NavItem active={view === "library"} icon={<Library size={18} />} label="Tu biblioteca" onClick={() => nav("library")} /></nav>
        <div className="mt-auto border-t border-white/[.07] pt-6"><p className="mb-3 font-mono text-[9px] uppercase tracking-[.25em] text-white/35">Estado de fuente</p><p className="flex items-center gap-2 font-mono text-[10px] text-[#55ff9a]"><span className="h-2 w-2 rounded-full bg-[#55ff9a] shadow-[0_0_8px_#55ff9a]" />{status.data?.spotifyConfigured ? "SPOTIFY ONLINE" : "MUSICBRAINZ ONLINE"}</p><p className="mt-2 font-mono text-[9px] uppercase tracking-wider text-white/30">Jamendo {status.data?.providers?.jamendo.openUntil && status.data.providers.jamendo.openUntil > Date.now() ? "pausado" : status.data?.providers?.jamendo.lastLatencyMs ? `${status.data.providers.jamendo.lastLatencyMs}ms` : "listo"} · Audius {status.data?.providers?.audius.openUntil && status.data.providers.audius.openUntil > Date.now() ? "pausado" : status.data?.providers?.audius.lastLatencyMs ? `${status.data.providers.audius.lastLatencyMs}ms` : "listo"}</p></div>
      </aside>
      <section className="min-w-0 flex-1">
        <header className="sticky top-0 z-10 flex items-center gap-4 border-b border-white/[.07] bg-[#07080c]/90 px-5 py-4 backdrop-blur-xl sm:px-8"><div className="flex gap-2"><button className="hidden h-8 w-8 place-items-center rounded-full bg-white/5 text-white/50 hover:bg-white/10 lg:grid"><ChevronLeft size={16} /></button><button className="hidden h-8 w-8 place-items-center rounded-full bg-white/5 text-white/50 hover:bg-white/10 lg:grid"><ChevronRight size={16} /></button></div><form onSubmit={submit} className="relative max-w-xl flex-1">{search.isFetching ? <Loader2 className="absolute left-4 top-1/2 -translate-y-1/2 animate-spin text-[#00e7ff]" size={17} /> : <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-white/40" size={17} />}<Input aria-label="Buscar música" value={term} onChange={e => setTerm(e.target.value)} onFocus={() => view !== "search" && setView("search")} placeholder="¿Qué querés escuchar?" className="h-11 rounded-full border-white/10 bg-white/[.07] pl-11 text-sm text-white placeholder:text-white/35 focus-visible:border-[#00e7ff]/60 focus-visible:ring-[#00e7ff]/20" /></form>{getLiveSearchQuery(term, submitted) && <span className="hidden font-mono text-[9px] uppercase tracking-[.18em] text-[#00e7ff] lg:block" role="status">Interpretando señal…</span>}<div className="hidden items-center gap-2 font-mono text-[10px] uppercase tracking-wider text-white/35 sm:flex"><span className="h-2 w-2 rounded-full bg-[#55ff9a]" /> {search.isFetching ? "Scanning" : "Local mode"}</div></header>
        <div className="p-5 sm:p-8 lg:p-10">
          {view === "home" && <HomeView onSearch={value => { setActiveStation(null); setTerm(value); setView("search"); setSubmitted(value); setOffset(0); setTracks([]); }} favorites={library.favorites.length} starterStations={starterStations} starterLoading={afterglowSearch.isFetching || neonFocusSearch.isFetching || openFrequencySearch.isFetching || freeJazzSearch.isFetching || riotFolkSearch.isFetching} activeStation={activeStation} onStationSelect={startStationSession} onPlay={playTrack} continueTracks={queueTracks} />}
          {view === "library" && <section><div className="mb-8 flex items-end justify-between gap-4"><SectionTitle eyebrow="Tu espacio" title="Tu biblioteca" /><button onClick={createPlaylist} className="mb-1 inline-flex shrink-0 items-center gap-2 border border-[#ff2db2]/50 px-3 py-2 font-mono text-[10px] uppercase tracking-wider text-[#ff65c8] transition hover:bg-[#ff2db2]/10 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#00e7ff]" aria-label="Crear playlist local"><ListMusic size={14} /> Nueva playlist</button></div><div className="mb-8 grid grid-cols-2 gap-3 sm:grid-cols-4"><Stat icon={<Heart size={16} />} label="Favoritos" value={library.favorites.length.toString()} /><Stat icon={<ListMusic size={16} />} label="En cola" value={library.queue.length.toString()} /><Stat icon={<Clock3 size={16} />} label="Guardado local" value="Sí" /></div>{library.playlists.length > 0 && <div className="mb-8"><p className="mb-3 font-mono text-[10px] uppercase tracking-[.25em] text-[#ff2db2]">Playlists locales</p><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{library.playlists.map(playlist => <div key={playlist.id} className="border border-white/[.08] bg-white/[.03] p-4"><div className="flex items-center justify-between gap-3"><p className="truncate font-display font-bold">{playlist.name}</p><ListMusic size={16} className="shrink-0 text-[#00e7ff]" /></div><p className="mt-2 font-mono text-[10px] uppercase tracking-wider text-white/35">{playlist.trackIds.length} señales guardadas</p></div>)}</div></div>}{visibleTracks.length ? <TrackGrid tracks={visibleTracks} favorites={library.favorites} onFavorite={toggleFavorite} onQueue={addToQueue} onPlaylist={addToPlaylist} onSelect={setSelected} onPlay={playTrack} /> : <EmptyLibrary onSearch={() => nav("search")} />}</section>}
          {view === "search" && <section><SectionTitle eyebrow={submitted ? "Resultados para" : "Explorar"} title={submitted || "Encontrá tu próxima señal"} />{getLiveSearchQuery(term, submitted) && <div className="mb-6 border border-[#00e7ff]/20 bg-[#00e7ff]/[.04] px-4 py-3 font-mono text-[10px] uppercase tracking-[.18em] text-[#00e7ff]" role="status">Búsqueda instantánea · artistas · álbumes · canciones</div>}{search.error && <div className="mb-6 border border-[#ff4d6d]/40 bg-[#ff4d6d]/5 p-4 font-mono text-xs text-[#ff9aaa]">No pudimos completar la búsqueda. Probá de nuevo en unos segundos.</div>}{search.isFetching && !tracks.length && <div className="grid place-items-center py-24"><Loader2 className="animate-spin text-[#00e7ff]" /></div>}{visibleTracks.length ? <><TrackGrid tracks={visibleTracks} favorites={library.favorites} onFavorite={toggleFavorite} onQueue={addToQueue} onPlaylist={addToPlaylist} onSelect={setSelected} onPlay={playTrack} />{search.data?.nextOffset !== null && search.data?.nextOffset !== undefined && <div className="mt-10 text-center"><Button onClick={() => setOffset(search.data!.nextOffset!)} variant="outline" className="rounded-full border-white/15 bg-white/5 px-6 font-mono text-xs text-white hover:bg-white/10">Ver más</Button></div>}</> : !search.isFetching && submitted && <div className="py-20 text-center text-white/45"><Search className="mx-auto mb-4 text-[#00e7ff]" /><p>No encontramos resultados relevantes para «{submitted}».</p><p className="mt-2 text-xs text-white/25">Probá con el nombre de un artista, álbum o canción.</p></div>}</section>}
        </div>
        <PreparedQueue items={autoplayQueue} onPlay={playTrack} />
        <PlaybackQueue items={queueTracks} suggestions={playableTracks} onPlay={playTrack} onRemove={removeFromQueue} onClear={clearQueue} onExplore={() => nav("search")} />
      </section>
    </div>
    <MobileNav view={view} onChange={nav} />
    {playbackNotice && <div role="status" className="fixed bottom-24 left-1/2 z-50 -translate-x-1/2 border border-[#ffb000]/50 bg-[#19140a] px-4 py-3 text-center font-mono text-[10px] uppercase tracking-[.12em] text-[#ffd166] shadow-[0_0_24px_rgba(255,176,0,.18)]">{playbackNotice}</div>}
    <Player active={Boolean(playing)} track={playing ?? IDLE_TRACK} lyricLine={activeLyric ?? undefined} isPlaying={isPlaying} currentTime={currentTime} duration={duration} volume={volume} onTimeUpdate={setCurrentTime} onLoadedMetadata={setDuration} onVolumeChange={changeVolume} muted={muted} onToggleMute={toggleMute} onPlay={() => playing && setIsPlaying(value => !value)} onPlaybackError={(error) => { setIsPlaying(false); setPlaybackNotice(getPlaybackErrorMessage(error)); }} onNext={advanceTrack} onPrevious={() => moveTrack(-1)} onClose={() => { setPlaying(null); setIsPlaying(false); }} />
    {selected && <Detail track={selected} lyrics={lyrics.data?.text || lyrics.data?.message} lyricsStatus={lyrics.data?.status} hasPreview={Boolean(selected.previewUrl)} isFavorite={library.favorites.includes(selected.id)} onFavorite={() => toggleFavorite(selected)} onPlay={() => playTrack(selected)} onClose={() => setSelected(null)} />}
  </main>;
}

function NavItem({ active, icon, label, onClick }: { active: boolean; icon: React.ReactNode; label: string; onClick: () => void }) { return <button onClick={onClick} className={`flex w-full items-center gap-3 rounded-md px-3 py-3 text-sm transition focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#00e7ff] ${active ? "bg-[#ff2db2]/10 text-[#ff65c8]" : "text-white/50 hover:bg-white/5 hover:text-white"}`}>{icon}<span>{label}</span></button>; }
function MobileNav({ view, onChange }: { view: View; onChange: (view: View) => void }) { return <nav className="fixed bottom-0 left-0 right-0 z-30 flex justify-around border-t border-white/10 bg-[#0a0b10]/95 p-3 backdrop-blur-xl lg:hidden"><NavItem active={view === "home"} icon={<HomeIcon size={18} />} label="Inicio" onClick={() => onChange("home")} /><NavItem active={view === "search"} icon={<Search size={18} />} label="Buscar" onClick={() => onChange("search")} /><NavItem active={view === "library"} icon={<Library size={18} />} label="Biblioteca" onClick={() => onChange("library")} /></nav>; }
function SectionTitle({ eyebrow, title }: { eyebrow: string; title: string }) { return <div className="mb-8"><p className="mb-2 font-mono text-[10px] uppercase tracking-[.3em] text-[#00e7ff]">{eyebrow}</p><h2 className="font-display text-3xl font-black tracking-tight sm:text-4xl">{title}</h2></div>; }
function Stat({ icon, label, value }: { icon: React.ReactNode; label: string; value: string }) { return <div className="border border-white/[.08] bg-white/[.03] p-4"><div className="mb-3 text-[#ff2db2]">{icon}</div><p className="font-mono text-[10px] uppercase text-white/35">{label}</p><p className="mt-1 font-display text-xl font-bold">{value}</p></div>; }
type RadioStation = { name: string; query: string; detail: string; artUrl: string; tracks: Track[] };
function HomeView({ onSearch, favorites, starterStations, starterLoading, activeStation, onStationSelect, onPlay, continueTracks }: { onSearch: (value: string) => void; favorites: number; starterStations: RadioStation[]; starterLoading: boolean; activeStation: string | null; onStationSelect: (station: RadioStation) => void; onPlay: (track: Track) => void; continueTracks: Track[] }) {
  return <>
    <section className="relative overflow-hidden rounded-2xl border border-white/[.08] bg-gradient-to-br from-[#191022] via-[#0d111b] to-[#090b11] p-6 sm:p-10 lg:p-12">
      <div className="absolute -right-24 -top-32 h-80 w-80 rounded-full bg-[#ff2db2]/15 blur-3xl" />
      <div className="absolute -bottom-24 left-1/3 h-64 w-64 rounded-full bg-[#00e7ff]/10 blur-3xl" />
      <div className="relative grid items-center gap-10 lg:grid-cols-[.8fr_1.2fr]">
        <div>
          <p className="mb-4 font-mono text-[10px] uppercase tracking-[.35em] text-[#ff2db2]">nowarfy · Sonic//Void Radio</p>
          <h2 className="max-w-xl font-display text-4xl font-black leading-[.95] tracking-[-.05em] sm:text-6xl">Señales<br /><span className="neon-cyan">fuera del radar.</span></h2>
          <p className="mt-5 max-w-lg text-sm leading-6 text-white/50">Estaciones de música independiente y catálogos con audio autorizado. Cada círculo muestra únicamente pistas que nowarfy puede reproducir dentro del sitio.</p>
        </div>
        <div className="relative flex min-h-[250px] items-center justify-center sm:min-h-[330px]" aria-label="Señales de radio disponibles">
          <div className="absolute h-48 w-48 rounded-full border border-[#00e7ff]/20 shadow-[0_0_80px_rgba(0,231,255,.12)] sm:h-64 sm:w-64" />
          <div className="absolute h-64 w-64 rounded-full border border-[#ff2db2]/15 sm:h-80 sm:w-80" />
          <div className="relative grid grid-cols-3 gap-3 sm:gap-5">
            {starterStations.slice(0, 5).map((station) => { const track = station.tracks[0]; return <article key={station.name} className="group relative w-[76px] text-center sm:w-[98px]">
              <button onClick={() => onStationSelect(station)} className="relative mx-auto block h-[76px] w-[76px] overflow-hidden rounded-full border-2 border-[#00e7ff]/45 bg-[#11131b] shadow-[0_0_22px_rgba(0,231,255,.16)] transition duration-300 hover:scale-110 hover:border-[#ff2db2] hover:shadow-[0_0_30px_rgba(255,45,178,.3)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#00e7ff]" aria-label={track ? `Reproducir estación ${station.name}` : `Explorar estación ${station.name}`}>
                {track ? <Cover track={track} /> : <img src={station.artUrl} alt={`Arte de la estación ${station.name}`} className="h-full w-full object-cover" />}
                <span className="absolute inset-0 grid place-items-center bg-black/0 text-white opacity-0 transition group-hover:bg-black/45 group-hover:opacity-100"><Play size={22} fill="currentColor" /></span>
              </button>
              <p className="mt-2 truncate font-display text-[11px] font-bold text-white/85 sm:text-xs">{station.name}</p>
              <p className={`truncate font-mono text-[8px] uppercase tracking-wider ${activeStation === station.name ? "text-[#ff65c8]" : "text-white/35"}`}>{activeStation === station.name ? "sesión activa" : track ? "playable" : "esperando audio"}</p>
            </article>; })}
          </div>
          {starterLoading && <Loader2 className="absolute bottom-2 right-2 animate-spin text-[#00e7ff]" size={16} aria-label="Cargando señales" />}
        </div>
      </div>
    </section>
    <HomeRows stations={starterStations} continueTracks={continueTracks} onPlay={onPlay} />
    <div className="mt-10"><SectionTitle eyebrow="Tu espacio" title="Accesos rápidos" /><div className="grid gap-4 sm:grid-cols-3"><QuickCard icon={<Heart />} title="Favoritos" detail={`${favorites} guardados`} onClick={() => onSearch(" ")} /><QuickCard icon={<Compass />} title="Descubrí" detail="Explorá música disponible" onClick={() => onSearch("underground")} /><QuickCard icon={<ListMusic />} title="Tu cola" detail="Preparada para después" onClick={() => onSearch(" ")} /></div></div>
  </>;
}

export function HomeRows({ stations, continueTracks, onPlay }: { stations: RadioStation[]; continueTracks: Track[]; onPlay: (track: Track) => void }) { const catalog = dedupePlayableTracks(stations.flatMap(station => station.tracks)); const popular = [...catalog].sort((a, b) => b.popularity - a.popularity).slice(0, 8); const recommended = [...catalog].sort((a, b) => (b.popularity + (b.source === "jamendo" ? 4 : 0)) - (a.popularity + (a.source === "jamendo" ? 4 : 0))).slice(0, 8); return <section className="mt-12 space-y-10" aria-label="Catálogo de música disponible"><RadioRow eyebrow="Más escuchado" title="Lo que está sonando" tracks={popular} onPlay={onPlay} empty="Todavía no hay suficientes pistas reproducibles para ordenar esta fila." /><RadioRow eyebrow="Recomendados" title="Elegidos para entrar directo" tracks={recommended} onPlay={onPlay} empty="Las fuentes están respondiendo; esta fila aparecerá cuando haya audio disponible." /><RadioRow eyebrow="Seguí vos" title="Continuá desde tu cola" tracks={continueTracks.filter(isPlayableTrack)} onPlay={onPlay} empty="Todavía no hay una cola local. Elegí una estación para empezar." /></section>; }
function RadioRow({ eyebrow, title, tracks, onPlay, empty }: { eyebrow: string; title: string; tracks: Track[]; onPlay: (track: Track) => void; empty: string }) { return <section><div className="mb-4 flex items-end justify-between gap-4"><div><p className="mb-1 font-mono text-[10px] uppercase tracking-[.3em] text-[#ff2db2]">{eyebrow}</p><h3 className="font-display text-2xl font-black tracking-tight sm:text-3xl">{title}</h3></div>{tracks.length > 0 && <span className="font-mono text-[10px] uppercase tracking-wider text-white/30">{tracks.length} disponibles</span>}</div>{tracks.length ? <div className="flex snap-x gap-4 overflow-x-auto pb-3 [scrollbar-color:#00e7ff33_transparent]">{tracks.map(track => <article key={`${track.source}-${track.id}`} className="group min-w-[155px] snap-start sm:min-w-[185px]"><button onClick={() => onPlay(track)} aria-label={`Reproducir ${track.name}`} className="relative block aspect-square w-full overflow-hidden border border-white/[.08] bg-[#11131b] text-left transition duration-300 hover:-translate-y-1 hover:border-[#00e7ff]/60 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#00e7ff]"><Cover track={track} /><span className="absolute bottom-3 right-3 grid h-9 w-9 place-items-center rounded-full bg-[#ff2db2] text-black opacity-90 shadow-[0_0_18px_rgba(255,45,178,.35)] transition group-hover:scale-110"><Play size={15} fill="currentColor" /></span></button><p className="mt-3 truncate font-display text-sm font-bold">{track.name}</p><p className="truncate text-xs text-white/45">{track.artist}</p><p className="mt-1 truncate font-mono text-[9px] uppercase tracking-wider text-[#00e7ff]/70">{track.source} · audio</p></article>)}</div> : <div className="border border-dashed border-white/10 bg-white/[.02] p-5 text-sm text-white/45">{empty}</div>}</section>; }

export function StarterRadio({ stations, loading, onStationSelect, onPlay }: { stations: RadioStation[]; loading: boolean; onStationSelect: (station: RadioStation) => void; onPlay: (track: Track) => void }) { return <section className="mt-12"><div className="mb-5 flex items-end justify-between gap-4"><div><p className="mb-2 font-mono text-[10px] uppercase tracking-[.3em] text-[#ff2db2]">nowarfy radio</p><h3 className="font-display text-2xl font-black">Playlists para entrar directo</h3></div><span className="hidden font-mono text-[10px] uppercase tracking-wider text-white/35 sm:block">Audio autorizado</span></div><div className="grid gap-4 md:grid-cols-3">{stations.map((station, index) => <button key={station.name} onClick={() => onStationSelect(station)} className="group relative overflow-hidden border border-white/[.08] bg-gradient-to-br from-[#141021] to-[#0b1018] p-5 text-left transition hover:-translate-y-1 hover:border-[#00e7ff]/50 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#00e7ff]"><div className="absolute -right-8 -top-8 h-28 w-28 rounded-full bg-[#00e7ff]/10 blur-2xl transition group-hover:bg-[#ff2db2]/20" /><div className="relative"><div className="mb-8 flex items-center justify-between"><span className="grid h-10 w-10 place-items-center rounded-full border border-[#00e7ff]/40 text-[#00e7ff]"><Play size={16} fill="currentColor" /></span><span className="font-mono text-[9px] uppercase tracking-wider text-white/30">señal / 0{index + 1}</span></div><p className="font-display text-xl font-bold">{station.name}</p><p className="mt-1 text-xs text-white/45">{station.detail}</p><p className="mt-5 font-mono text-[10px] uppercase tracking-wider text-[#00e7ff]">Explorar señal →</p></div></button>)}</div><div className="mt-10"><div className="mb-4 flex items-center justify-between"><div><p className="mb-1 font-mono text-[10px] uppercase tracking-[.3em] text-[#00e7ff]">Señales disponibles ahora</p><h3 className="font-display text-2xl font-black">Recomendado para empezar</h3></div>{loading && <Loader2 className="animate-spin text-[#00e7ff]" size={18} />}</div>{stations.some(station => station.tracks.length) ? <div className="grid gap-5 sm:grid-cols-2 xl:grid-cols-4">{stations.flatMap(station => station.tracks.slice(0, 2).map(track => ({ track, station }))).slice(0, 4).map(({ track, station }) => <article key={`${track.source}-${track.id}`} className="group border border-white/[.08] bg-white/[.03] p-3 transition hover:border-[#ff2db2]/40"><div className="aspect-square overflow-hidden bg-[#151722]"><Cover track={track} /></div><p className="mt-3 truncate font-display font-bold">{track.name}</p><p className="truncate text-xs text-white/45">{track.artist}</p><button onClick={() => onPlay(track)} className="mt-3 w-full border border-[#00e7ff]/30 py-2 font-mono text-[10px] uppercase tracking-wider text-[#00e7ff] transition hover:bg-[#00e7ff]/10"><Play size={12} className="mr-1 inline" fill="currentColor" /> Play · {station.name}</button></article>)}</div> : !loading && <div className="border border-white/[.08] bg-white/[.02] p-5 text-sm text-white/45">No hay una señal inicial disponible en este momento. Las playlists de arriba siguen listas para explorar.</div>}</div></section>; }
function QuickCard({ icon, title, detail, onClick }: { icon: React.ReactNode; title: string; detail: string; onClick: () => void }) { return <button onClick={onClick} className="group flex items-center gap-4 border border-white/[.08] bg-white/[.03] p-5 text-left transition focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#00e7ff] hover:-translate-y-1 hover:border-[#00e7ff]/40 hover:bg-white/[.06]"><span className="text-[#00e7ff] transition group-hover:text-[#ff2db2]">{icon}</span><span><b className="block font-display">{title}</b><small className="mt-1 block text-xs text-white/40">{detail}</small></span></button>; }
export function TrackGrid({ tracks, favorites, onFavorite, onQueue, onPlaylist, onSelect, onPlay }: { tracks: Track[]; favorites: string[]; onFavorite: (track: Track) => void; onQueue: (track: Track) => void; onPlaylist: (track: Track) => void; onSelect: (track: Track) => void; onPlay: (track: Track) => void }) { return <div className="grid gap-5 sm:grid-cols-2 xl:grid-cols-4">{tracks.filter(isPlayableTrack).map(track => <article key={`${track.source}-${track.id}`} className="group relative overflow-hidden rounded-lg border border-white/[.07] bg-[#0d0f15] transition hover:-translate-y-1 hover:border-[#00e7ff]/40 hover:shadow-[0_14px_32px_rgba(0,0,0,.3)]"><button onClick={() => onSelect(track)} className="block w-full text-left focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-[#00e7ff]"><div className="aspect-square overflow-hidden bg-[#151722]"><Cover track={track} /></div><div className="p-4"><div className="mb-2 flex items-center justify-between"><span className="font-mono text-[9px] uppercase tracking-wider text-[#00e7ff]">{track.matchMode === "discovery" ? "Jamendo · descubrimiento" : track.kind === "album" ? "Álbum" : "Canción"}</span><span className="font-mono text-[9px] text-white/30">{track.releaseYear}</span></div><h3 className="truncate font-display font-bold">{track.name}</h3><p className="mt-1 truncate text-sm text-white/45">{track.artist}</p></div></button><div className="flex items-center justify-between border-t border-white/[.06] px-4 py-3"><button onClick={() => onPlay(track)} className="grid h-8 w-8 place-items-center rounded-full bg-[#ff2db2] text-black transition hover:scale-105 disabled:cursor-not-allowed disabled:opacity-35 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#00e7ff]" aria-label={`Reproducir ${track.name}`} title={track.previewUrl ? "Reproducir preview" : "Audio no disponible para esta fuente"}><Play size={14} fill="currentColor" /></button><div className="flex items-center gap-4"><button onClick={() => onQueue(track)} className="text-white/30 transition hover:text-[#00e7ff]" aria-label="Agregar a la cola"><ListMusic size={16} /></button><button onClick={() => onPlaylist(track)} className="text-white/30 transition hover:text-[#ff65c8]" aria-label="Guardar en playlist local"><Library size={16} /></button><button onClick={() => onFavorite(track)} className={`transition ${favorites.includes(track.id) ? "text-[#ff2db2]" : "text-white/30 hover:text-white"}`} aria-label="Agregar a favoritos"><Heart size={17} fill={favorites.includes(track.id) ? "currentColor" : "none"} /></button></div></div></article>)}</div>; }
export function PreparedQueue({ items, onPlay }: { items: Track[]; onPlay: (track: Track) => void }) { const playable = items.filter(isPlayableTrack); if (!playable.length) return null; return <section className="mb-5 border border-[#ff2db2]/25 bg-[#ff2db2]/[.04] p-4" aria-label="A continuación"><div className="mb-3 flex items-center justify-between gap-3"><div><p className="font-mono text-[10px] uppercase tracking-[.25em] text-[#ff65c8]">A continuación</p><p className="mt-1 text-xs text-white/45">Preparadas antes de que termine la pista actual</p></div><span className="font-mono text-[10px] text-white/35">{playable.length} listas</span></div><div className="grid gap-2 sm:grid-cols-3">{playable.map((item, index) => <button key={`${item.source}-${item.id}`} onClick={() => onPlay(item)} className="flex min-w-0 items-center gap-3 border border-white/10 bg-black/20 p-3 text-left transition hover:border-[#00e7ff]/50 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#00e7ff]"><span className="font-mono text-[10px] text-[#00e7ff]">{String(index + 1).padStart(2, "0")}</span><span className="min-w-0"><span className="block truncate text-xs font-bold">{item.name}</span><span className="mt-1 block truncate text-[10px] text-white/40">{item.artist} · {item.source}</span></span></button>)}</div></section>; }
export function PlaybackQueue({ items, suggestions, onPlay, onRemove, onClear, onExplore }: { items: Track[]; suggestions: Track[]; onPlay: (track: Track) => void; onRemove: (trackId: string) => void; onClear: () => void; onExplore: () => void }) { const playableItems = items.filter(item => Boolean(item.previewUrl)); const playableSuggestions = suggestions.filter(item => Boolean(item.previewUrl)); const choices = playableItems.length ? playableItems : playableSuggestions.slice(0, 4); return <section className="mb-8 border border-[#00e7ff]/20 bg-[#00e7ff]/[.04] p-4 sm:p-5" aria-label="Cola de reproducción"><div className="mb-4 flex flex-wrap items-center justify-between gap-3"><div><p className="font-mono text-[10px] uppercase tracking-[.25em] text-[#00e7ff]">Línea de reproducción</p><p className="mt-1 text-xs text-white/45">Solo pistas con audio autorizado disponible</p></div><div className="flex items-center gap-3"><span className="font-mono text-[10px] text-white/35">{playableItems.length} en cola</span>{playableItems.length > 0 && <button onClick={onClear} className="font-mono text-[10px] uppercase tracking-wider text-white/40 hover:text-[#ff65c8]">Vaciar</button>}</div></div>{choices.length > 0 ? <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{choices.map(item => <article key={`${item.source}-${item.id}`} className="border border-white/10 bg-black/20 p-3"><button onClick={() => onPlay(item)} className="block w-full text-left focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#00e7ff]"><p className="truncate text-xs font-bold">{item.name}</p><p className="mt-1 truncate text-[11px] text-white/45">{item.artist}</p><p className="mt-2 truncate font-mono text-[9px] uppercase text-[#ffb000]">{item.licenseLabel}</p><p className="mt-1 truncate text-[10px] text-white/35">Atribución: {item.attribution}</p></button><div className="mt-3 flex items-center justify-between gap-2">{item.licenseUrl ? <a href={item.licenseUrl} target="_blank" rel="noreferrer" className="truncate text-[10px] text-[#00e7ff]/75 hover:text-[#00e7ff]">Ver licencia/fuente</a> : <span className="text-[10px] text-white/25">Fuente no disponible</span>}{playableItems.length > 0 && <button onClick={() => onRemove(item.id)} className="shrink-0 text-[10px] text-white/35 hover:text-[#ff65c8]" aria-label={`Quitar ${item.name}`}>Quitar</button>}</div></article>)}</div> : <div className="flex flex-wrap items-center justify-between gap-3 border border-dashed border-white/10 p-4"><p className="text-sm text-white/50">Todavía no hay pistas reproducibles en esta cola.</p><button onClick={onExplore} className="rounded-full border border-[#00e7ff]/50 px-4 py-2 font-mono text-[10px] uppercase tracking-wider text-[#00e7ff] hover:bg-[#00e7ff]/10">Explorar audio disponible</button></div>}</section>; }
function EmptyLibrary({ onSearch }: { onSearch: () => void }) { return <div className="border border-dashed border-white/10 py-24 text-center"><Heart className="mx-auto mb-4 text-[#ff2db2]" /><p className="text-white/50">Tu biblioteca todavía está vacía.</p><button onClick={onSearch} className="mt-4 text-sm text-[#00e7ff] hover:text-white">Buscar música</button></div>; }

export function spectrumToBarLevel(value: number, envelope: number) { const normalized = Math.min(1, Math.max(0, value)); return Math.max(0, envelope) * (0.28 + normalized * 0.72); }

export function AudioVisualizer({ isPlaying, currentTime, audioElement }: { isPlaying: boolean; currentTime: number; audioElement?: HTMLAudioElement | null }) { const canvasRef = useRef<HTMLCanvasElement>(null); const analyserRef = useRef<AnalyserNode | null>(null); const [reducedMotion, setReducedMotion] = useState(false); useEffect(() => { const media = typeof window.matchMedia === "function" ? window.matchMedia("(prefers-reduced-motion: reduce)") : null; const update = () => setReducedMotion(Boolean(media?.matches)); update(); media?.addEventListener?.("change", update); return () => media?.removeEventListener?.("change", update); }, []); useEffect(() => { if (!audioElement || !isPlaying) return; try { const graph = getOrCreateVisualAudioGraph(audioElement); if (!graph) return; analyserRef.current = graph.analyser; void graph.context.resume(); } catch { analyserRef.current = null; } return () => { analyserRef.current = null; }; }, [audioElement, isPlaying]); useEffect(() => { const canvas = canvasRef.current; if (!canvas) return; const context = canvas.getContext("2d"); if (!context) return; let frame = 0; const draw = (now: number) => { const width = Math.max(1, canvas.clientWidth); const height = Math.max(1, canvas.clientHeight); const ratio = Math.min(window.devicePixelRatio || 1, 2); if (canvas.width !== Math.round(width * ratio) || canvas.height !== Math.round(height * ratio)) { canvas.width = Math.round(width * ratio); canvas.height = Math.round(height * ratio); } context.setTransform(ratio, 0, 0, ratio, 0, 0); context.clearRect(0, 0, width, height); const bars = 24; const gap = 2; const barWidth = Math.max(1, (width - gap * (bars - 1)) / bars); const time = isPlaying && !reducedMotion ? now / 360 : currentTime * 2; const spectrum = analyserRef.current ? new Uint8Array(analyserRef.current.frequencyBinCount) : null; if (spectrum) analyserRef.current?.getByteFrequencyData(spectrum); for (let index = 0; index < bars; index += 1) { const envelope = Math.sin((index / bars) * Math.PI) * 0.72 + 0.28; const realLevel = spectrum ? spectrum[index % spectrum.length] / 255 : 0; const pulse = isPlaying && realLevel > 0.015 ? realLevel : isPlaying ? (Math.sin(time + index * 0.58) + Math.sin(time * 0.63 + index * 0.19) + 2) / 4 : 0.16 + envelope * 0.08; const barHeight = Math.max(3, (height - 4) * spectrumToBarLevel(pulse, envelope)); const x = index * (barWidth + gap); const y = height - barHeight; const gradient = context.createLinearGradient(0, y, 0, height); gradient.addColorStop(0, index % 3 === 0 ? "#ff65c8" : "#00e7ff"); gradient.addColorStop(1, "#ff2db2"); context.fillStyle = gradient; context.globalAlpha = isPlaying ? 0.95 : 0.38; context.fillRect(x, y, barWidth, barHeight); } context.globalAlpha = 1; if (!reducedMotion && isPlaying) frame = window.requestAnimationFrame(draw); }; draw(0); return () => window.cancelAnimationFrame(frame); }, [currentTime, isPlaying, reducedMotion]); return <div className="w-16 shrink-0 sm:w-28" role="img" aria-label={isPlaying ? "Ecualizador visual activo" : "Ecualizador visual en pausa"}><canvas ref={canvasRef} className="h-8 w-full" /></div>; }

export function Player({ active, track, lyricLine, isPlaying, currentTime, duration, volume, muted, onTimeUpdate, onLoadedMetadata, onVolumeChange, onToggleMute, onPlay, onPlaybackError, onNext, onPrevious, onClose }: { active: boolean; track: Track; lyricLine?: string; isPlaying: boolean; currentTime: number; duration: number; volume: number; muted: boolean; onTimeUpdate: (value: number) => void; onLoadedMetadata: (value: number) => void; onVolumeChange: (value: number) => void; onToggleMute: () => void; onPlay: () => void; onPlaybackError: (error?: unknown) => void; onNext: () => void; onPrevious: () => void; onClose: () => void }) { const audioRef = useRef<HTMLAudioElement>(null); const [audioElement, setAudioElement] = useState<HTMLAudioElement | null>(null); const [reducedMotion, setReducedMotion] = useState(false); const availability = getPlaybackAvailability(track.previewUrl); useEffect(() => { const media = typeof window.matchMedia === "function" ? window.matchMedia("(prefers-reduced-motion: reduce)") : null; const update = () => setReducedMotion(Boolean(media?.matches)); update(); media?.addEventListener?.("change", update); return () => media?.removeEventListener?.("change", update); }, []); useEffect(() => { if (!audioRef.current || !track.previewUrl) return; audioRef.current.volume = volume; audioRef.current.muted = muted; if (isPlaying) void audioRef.current.play().catch(error => onPlaybackError(error)); else audioRef.current.pause(); }, [isPlaying, track.previewUrl, volume, muted, onPlaybackError]); useEffect(() => { if (!("mediaSession" in navigator)) return; navigator.mediaSession.metadata = new MediaMetadata({ title: track.name, artist: track.artist, album: track.album, artwork: track.imageUrl ? [{ src: track.imageUrl, sizes: "500x500" }] : [] }); navigator.mediaSession.setActionHandler("play", onPlay); navigator.mediaSession.setActionHandler("pause", onPlay); navigator.mediaSession.setActionHandler("nexttrack", onNext); navigator.mediaSession.setActionHandler("previoustrack", onPrevious); return () => { navigator.mediaSession.metadata = null; }; }, [track, onNext, onPrevious, onPlay]); return <div className="fixed bottom-0 left-0 right-0 z-40 border-t border-white/10 bg-[#101118]/95 px-4 py-3 shadow-[0_-10px_30px_rgba(0,0,0,.35)] backdrop-blur-xl">{lyricLine && <div className="mx-auto mb-2 max-w-[1600px] truncate text-center font-display text-sm font-bold text-[#00e7ff]" aria-live="polite">{lyricLine}</div>}<div className="mx-auto flex max-w-[1600px] items-center gap-4"><div className="h-12 w-12 shrink-0 overflow-hidden bg-[#171923]"><Cover track={track} /></div><div className="min-w-0 flex-1"><p className="truncate text-sm font-bold">{active ? track.name : "Sonic//Void listo"}</p><p className="truncate text-xs text-white/40">{active ? track.artist : "Elegí una señal para comenzar"}</p>{active && <a href={track.spotifyUrl} target="_blank" rel="noreferrer" className="mt-1 inline-block font-mono text-[9px] uppercase tracking-wider text-[#00e7ff]/70 hover:text-[#00e7ff]">Fuente: {track.source}{track.matchMode === "discovery" ? " · descubrimiento" : ""}</a>}</div><FullSignal audioElement={audioElement} isPlaying={isPlaying} reducedMotion={reducedMotion} /><ButterchurnVisualizer audioElement={audioElement} isPlaying={isPlaying} reducedMotion={reducedMotion} fallback={<AudioVisualizer isPlaying={isPlaying} currentTime={currentTime} audioElement={audioElement} />} /><div className="hidden items-center gap-5 sm:flex"><button onClick={onPrevious} disabled={!active} className="text-white/40 hover:text-white disabled:opacity-30 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#00e7ff]" aria-label="Pista anterior"><SkipBack size={17} fill="currentColor" /></button><button onClick={onPlay} disabled={!track.previewUrl} className="grid h-9 w-9 place-items-center rounded-full bg-white text-black hover:bg-[#00e7ff] disabled:cursor-not-allowed disabled:opacity-40" title={track.previewUrl ? "Reproducir preview" : "Esta fuente no ofrece preview de audio"}>{isPlaying ? <Pause size={15} fill="currentColor" /> : <Play size={15} fill="currentColor" />}</button><button onClick={onNext} disabled={!active} className="text-white/40 hover:text-white disabled:opacity-30 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#00e7ff]" aria-label="Pista siguiente"><SkipForward size={17} fill="currentColor" /></button></div><div className="hidden min-w-[220px] flex-1 items-center gap-3 md:flex"><span className="font-mono text-[9px] text-white/35">{formatTime(currentTime)}</span><input aria-label="Progreso de reproducción" type="range" min="0" max={duration || 1} value={Math.min(currentTime, duration || 1)} onChange={event => { const next = Number(event.target.value); onTimeUpdate(next); if (audioRef.current) audioRef.current.currentTime = next; }} className="h-1 w-full accent-[#ff2db2]" /><span className="font-mono text-[9px] text-white/35">{formatTime(duration)}</span></div><div className="hidden items-center gap-2 text-white/40 lg:flex"><button onClick={onToggleMute} className="text-white/45 transition hover:text-[#00e7ff] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#00e7ff]" aria-label={muted ? "Activar sonido" : "Silenciar"} aria-pressed={muted} title={muted ? "Activar sonido" : "Silenciar"}>{muted ? <VolumeX size={16} /> : <Volume2 size={16} />}</button><input aria-label="Volumen" type="range" min="0" max="1" step="0.01" value={volume} onChange={event => onVolumeChange(Number(event.target.value))} className="h-1 w-20 accent-[#00e7ff]" /></div>{availability === "unavailable" && <span className="hidden font-mono text-[9px] uppercase text-[#ffb000] lg:block">Preview no disponible</span>}<button onClick={onClose} className="text-white/30 hover:text-white">×</button></div>{availability === "ready" && <audio ref={node => { audioRef.current = node; setAudioElement(node); }} muted={muted} src={track.previewUrl ?? undefined} onPlay={() => undefined} onTimeUpdate={event => onTimeUpdate(event.currentTarget.currentTime)} onLoadedMetadata={event => onLoadedMetadata(event.currentTarget.duration)} onError={() => onPlaybackError()} onEnded={onNext} preload="none" />}</div>; }
function formatTime(value: number) { if (!Number.isFinite(value) || value <= 0) return "0:00"; return `${Math.floor(value / 60)}:${String(Math.floor(value % 60)).padStart(2, "0")}`; }
function Detail({ track, lyrics, lyricsStatus, hasPreview, isFavorite, onFavorite, onPlay, onClose }: { track: Track; lyrics?: string; lyricsStatus?: string; hasPreview: boolean; isFavorite: boolean; onFavorite: () => void; onPlay: () => void; onClose: () => void }) { const statusLabel = lyricsStatus === "available" ? "LRCLIB · sincronizadas" : lyricsStatus === "instrumental" ? "LRCLIB · instrumental" : lyricsStatus === "rate_limited" ? "LRCLIB · esperá un momento" : lyricsStatus === "not_found" ? "LRCLIB · no encontrada" : !hasPreview ? "Sin preview de audio" : "LRCLIB · consultando"; return <div className="fixed inset-0 z-50 grid place-items-center bg-black/80 p-4 backdrop-blur-md" onClick={onClose}><section onClick={event => event.stopPropagation()} className="max-h-[90vh] w-full max-w-3xl overflow-y-auto rounded-2xl border border-white/10 bg-[#0d0f15] p-6 sm:p-9"><div className="grid gap-8 sm:grid-cols-[220px_1fr]"><div className="aspect-square overflow-hidden rounded-lg bg-[#171923]"><Cover track={track} large /></div><div><p className="font-mono text-[10px] uppercase tracking-[.3em] text-[#00e7ff]">{track.kind === "album" ? "Álbum" : "Canción"} · {track.source}{track.matchMode === "discovery" ? " · descubrimiento" : ""}</p><h2 className="mt-3 font-display text-4xl font-black leading-none">{track.name}</h2><p className="mt-3 text-lg text-[#ff2db2]">{track.artist}</p><p className="mt-5 text-sm text-white/45">{track.album} · {track.releaseYear}</p><div className="mt-7 flex gap-3"><button onClick={onPlay} className="flex items-center gap-2 rounded-full bg-[#ff2db2] px-5 py-3 text-sm font-bold text-black disabled:cursor-not-allowed disabled:opacity-40" title={hasPreview ? "Reproducir preview" : "Esta fuente no entrega audio reproducible"}><Play size={15} fill="currentColor" /> {hasPreview ? "Play" : "Sin audio"}</button><button onClick={onFavorite} className={`grid h-11 w-11 place-items-center rounded-full border ${isFavorite ? "border-[#ff2db2] text-[#ff2db2]" : "border-white/15 text-white/50"}`}><Heart size={17} fill={isFavorite ? "currentColor" : "none"} /></button></div><a href={track.spotifyUrl} target="_blank" rel="noreferrer" className="mt-5 inline-flex items-center gap-2 text-xs text-white/40 hover:text-white">Abrir fuente oficial <ExternalLink size={13} /></a></div></div><div className="mt-10 border-t border-white/[.08] pt-7"><div className="flex items-center justify-between gap-3"><p className="font-mono text-[10px] uppercase tracking-[.3em] text-[#ff2db2]">Lyrics channel</p><span className="font-mono text-[9px] uppercase tracking-wider text-[#00e7ff]">{statusLabel}</span></div><p className="mt-4 whitespace-pre-line text-sm leading-7 text-white/45">{lyrics || (lyricsStatus === "rate_limited" ? "LRCLIB pidió esperar antes de volver a consultar." : lyricsStatus === "instrumental" ? "No hay letras porque esta pista figura como instrumental." : !hasPreview ? "Las letras pueden consultarse, pero la línea activa no avanzará sin una preview de audio autorizada." : "LRCLIB no tiene una coincidencia disponible para esta pista.")}</p></div><button onClick={onClose} className="mt-8 text-xs text-white/30 hover:text-white">Cerrar</button></section></div>; }
